{{ config(materialized='table') }}
-- Self-referencing table(s): 'AUDIT_SERVICE_ANNUALISED1' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
SELECT
CURRENT_DATE() AUDIT_DATE,
'AUDIT_BET_ACTUAL_NET_BOOKINGS_A_MY' AUDIT_NAME,
'N_BOOKINGS_MEASURE' SRC_TABLE_NAME,
'N_BOOKINGS_MEASURE' TGT_TABLE_NAME,
'NET_BOOKINGS_AMT' AMOUNT_NAME,
ACT.DV_FISCAL_YEAR_MTH_NUMBER_INT  SRC_FISCAL_YEAR_MTH_NUMBER_INT,
ACT.BKGS_MEASURE_TRANS_TYPE_CODE AS SRC_BKGS_MEASURE_TRANS_TYPE_CD,
ACT.BOOKINGS_PROCESS_DATE SRC_BOOKINGS_PROCESS_DATE,
ZEROIFNULL(DD_COMP_US_NET_PRICE_AMOUNT1) SRC_AMT,
ACT.DV_FISCAL_YEAR_MTH_NUMBER_INT TGT_FISCAL_YEAR_MTH_NUMBER_INT,
ACT.BKGS_MEASURE_TRANS_TYPE_CODE AS TGT_BKGS_MEASURE_TRANS_TYPE_CD,
ACT.BOOKINGS_PROCESS_DATE TGT_BOOKINGS_PROCESS_DATE,
ZEROIFNULL(ANNUAL_MY_AMT)TGT_AMT,
ZEROIFNULL(DD_COMP_US_NET_PRICE_AMOUNT1) - ZEROIFNULL(ANNUAL_MY_AMT) AUDIT_AMT,
CURRENT_USER AS EDW_CREATE_USER,
CURRENT_USER AS EDW_UPDATE_USER,
CURRENT_TIMESTAMP(0) AS EDW_CREATE_DATETIME,
CURRENT_TIMESTAMP(0) AS EDW_UPDATE_DATETIME
FROM
(
SELECT
NBM.DV_FISCAL_YEAR_MTH_NUMBER_INT,
BKGS_MEASURE_TRANS_TYPE_CODE,
BOOKINGS_PROCESS_DATE,
SUM(ZEROIFNULL(DD_COMP_US_NET_PRICE_AMOUNT  ))DD_COMP_US_NET_PRICE_AMOUNT1,
(SUM(ZEROIFNULL(DV_ANNUALIZED_US_NET_AMT)) + SUM(ZEROIFNULL(DV_MULTIYEAR_US_NET_AMT)))ANNUAL_MY_AMT
FROM
{{ source('raw', 'N_BOOKINGS_MEASURE') }} NBM
INNER JOIN
{{ source('raw', 'R_FISCAL_DAY_TO_YEAR') }} RDAYS
ON NBM.BOOKINGS_PROCESS_DATE = RDAYS.CALENDAR_DATE
INNER JOIN
{{ source('raw', 'R_FISCAL_MONTH_TO_YEAR') }} RFM
ON RFM.FISCAL_YEAR_AGE     IN (1,0)
/*ON (
( RFM.PREVIOUS_FSCL_MONTH_FLAG      = 'Y'  AND CURRENT_DATE BETWEEN RFM.FISCAL_MONTH_END_DATE + 1 AND  RFM.FISCAL_MONTH_END_DATE + 6) 
OR RFM.CURRENT_FISCAL_MONTH_FLAG    = 'Y'   
)*/
WHERE RFM.FISCAL_YEAR_MONTH_INT = NBM.DV_FISCAL_YEAR_MTH_NUMBER_INT
AND COLLATE( SERVICE_FLG, 'en-ci-rtrim') = 'Y'
GROUP BY 1,2,3
) ACT
WHERE  AUDIT_AMT NOT BETWEEN  -1 AND 1